import{c as n,Q as e,j as i,m as t}from"./chunks/framework.BXc4yaFE.js";const d=JSON.parse('{"title":"Enhancing Quantum Machine Learning with Anyons","description":"","frontmatter":{"url":"https://arxiv.org/abs/2606.16090","title":"Enhancing Quantum Machine Learning with Anyons","archived_date":"2026-07-25T00:00:00.000Z","arxiv_id":2606.1609,"authors":["Da Zhang","Wen-Qiang Liu","Zhaohui Wei","Zhang-Qi Yin"],"domain":"quantum-classical-machine-learning","published_date":"2026-06-15T00:00:00.000Z","source_routine":"routine-e"},"headers":[],"relativePath":"research/papers/2026-07-25-quantum-ml-anyons-2606-16090.md","filePath":"research/papers/2026-07-25-quantum-ml-anyons-2606-16090.md","lastUpdated":1785909234000}'),r={name:"research/papers/2026-07-25-quantum-ml-anyons-2606-16090.md"};function o(s,a,h,c,u,l){return e(),i("div",null,[...a[0]||(a[0]=[t('<h1 id="enhancing-quantum-machine-learning-with-anyons" tabindex="-1">Enhancing Quantum Machine Learning with Anyons <a class="header-anchor" href="#enhancing-quantum-machine-learning-with-anyons" aria-label="Permalink to &quot;Enhancing Quantum Machine Learning with Anyons&quot;">​</a></h1><h2 id="摘要-核心貢獻" tabindex="-1">摘要 / 核心貢獻 <a class="header-anchor" href="#摘要-核心貢獻" aria-label="Permalink to &quot;摘要 / 核心貢獻&quot;">​</a></h2><p>本文提出統一量子核框架，涵蓋 bosonic、fermionic、anyonic 三種交換統計。透過表徵層分析（分數交換相位可存取對稱/反對稱極限無法觸及的特徵空間方向）、核幾何分析（分離度提升、複雜度降低）與基準測試三個角度，證明 anyonic 核在多個基準上優於其他核。作者將粒子交換統計定位為量子機器學習領域先前被忽視的一種運算資源。</p><h2 id="為何屬「新領域」" tabindex="-1">為何屬「新領域」 <a class="header-anchor" href="#為何屬「新領域」" aria-label="Permalink to &quot;為何屬「新領域」&quot;">​</a></h2><p>以任意子（anyon）交換統計作為量子 ML 運算資源的理論框架，與 workspace 現有版圖無內容重疊；核心關鍵詞於三個既有集合反向 grep 命中皆為 0，與同批收錄的 2607.10563（議程）、2606.14822（工程）共同構成本次 quantum-classical-machine-learning 領域的理論層證據。</p>',5)])])}const p=n(r,[["render",o]]);export{d as __pageData,p as default};
